// GetSignedAttachment Download an attachment by signed URL
//
// Public download behind the `url` returned by `GET …/attachments/{attachmentId}?url=signed`; the HMAC token is the credential (bound to the organisation and the attachment, expires after `attachments.signedUrlTtl`). Streams the bytes with the same headers as the authenticated download. A tampered token is `403 signed_url_invalid`, an expired one `403 signed_url_expired`, an infected attachment `403 attachment_infected`. Read-only; no cookie or API key needed.
//
// Corresponds with GET /a/{token} (the `GetSignedAttachment` operationId).
func (c *Client) GetSignedAttachment(ctx context.Context, token string, reqEditors ...RequestEditorFn) (*http.Response, error) {
	req, err := NewGetSignedAttachmentRequest(c.Server, token)
	if err != nil {
		return nil, err
	}
	req = req.WithContext(ctx)
	if err := c.applyEditors(ctx, req, reqEditors); err != nil {
		return nil, err
	}
	return c.Client.Do(req)
}

