//
// Corresponds with POST /v1/accounts/{accountId}/exports (the `CreateAccountExport` operationId).
func (c *ClientWithResponses) CreateAccountExportWithResponse(ctx context.Context, accountId string, params *CreateAccountExportParams, body CreateAccountExportJSONRequestBody, reqEditors ...RequestEditorFn) (*CreateAccountExportResponse, error) {
	rsp, err := c.CreateAccountExport(ctx, accountId, params, body, reqEditors...)
	if err != nil {
		return nil, err
	}
	return ParseCreateAccountExportResponse(rsp)
}

